def GROUP(target, spec, scope):
    """
    Group mode dispatcher; also sentinel for current mode = group
    """
    r = lambda s: scope[glom](target, s, scope)
    t = scope[ACC_TREE]
    if callable(getattr(spec, "agg", None)):
        return spec.agg(target, t)
    if callable(spec):
        return spec(target)
    st = type(spec)
    if st not in (dict, list):
        raise BadSpec("Group mode expected dict, list, callable, or"
                      " aggregator, not: %r" % (spec,))
    sid = id(spec)
    acc = t.get(sid)
    if acc is None:
        acc = t[sid] = st()
    if st is dict:
        done = True
        for k, v in spec.items():
            if t.get(k) is STOP:
                continue
            key = r(k)
            if key is SKIP:
                done = False
                continue
            if key is STOP:
                t[k] = STOP
                continue
            if key not in acc:
                t[key] = {}
            scope[ACC_TREE] = t[key]
            res = r(v)
            if res is STOP:
                t[k] = STOP
                continue
            done = False
            if res is not SKIP:
                acc[key] = res
        return STOP if done else acc
    else:  # list
        for v in spec:
            if type(v) is dict:
                raise BadSpec('dicts within lists are not'
                              ' allowed while in Group mode: %r' % spec)
            res = r(v)
            if res is STOP:
                return STOP
            if res is not SKIP:
                acc.append(res)
        return acc
```

