def glomit(self, target, scope):
    o, a, p = self.op, self.arg, self.path
    dt, dp = (scope[UP], p.from_t()) if p.startswith(S) else (target, p)
    try:
        dest = scope[glom](dt, dp, scope)
    except PathAccessError:
        if not self.ignore_missing:
            raise
    else:
        exc_map = {'[': IndexError, '.': AttributeError, 'P': Exception}
        try:
            if o == '[':
                del dest[a]
            elif o == '.':
                delattr(dest, a)
            elif o == 'P':
                scope[TargetRegistry].get_handler('delete', dest)(dest, a)
        except exc_map[o] as e:
            if not self.ignore_missing:
                raise PathDeleteError(e, p, a) from e
    return target
