def __repr__(self):
    base_args = (self.subspec,) if self.subspec != T else ()
    base = format_invocation(self.__class__.__name__, base_args, repr=bbrepr)
    chunks = [base]
    for f, a, _ in reversed(self._iter_stack):
        m = getattr(self, f)
        fb = FunctionBuilder.from_func(m)
        fb.args = fb.args[1:]
        an = fb.get_arg_names()
        if len(a) > 1 and an:
            a, kw = (), list(zip(an, a))
        else:
            kw = []
        chunks.append('.' + format_invocation(f, a, kw, repr=bbrepr))
    return ''.join(chunks)
